using Microsoft.EntityFrameworkCore;

public sealed class DashboardQuery(ShopDb db)
{
    public async Task<Dashboard> LoadAsync(CancellationToken ct)
    {
        // All three start on the same context before any of them finishes
        var count = db.Orders.CountAsync(ct);
        var revenue = db.Orders.SumAsync(o => o.Total, ct);
        var top = db.Products.OrderByDescending(p => p.Sold)
            .Take(5).ToListAsync(ct);
        // Throws: a second operation was started on this context
        await Task.WhenAll(count, revenue, top);
        return new Dashboard(await count, await revenue, await top);
    }
}

using Microsoft.EntityFrameworkCore;

// Program.cs: builder.Services.AddDbContextFactory<ShopDb>(...)
public sealed class DashboardQuery(IDbContextFactory<ShopDb> factory)
{
    public async Task<Dashboard> LoadAsync(CancellationToken ct)
    {
        var count = RunAsync(db => db.Orders.CountAsync(ct), ct);
        var revenue = RunAsync(db => db.Orders.SumAsync(o => o.Total, ct), ct);
        var top = RunAsync(db => db.Products.OrderByDescending(p => p.Sold)
            .Take(5).ToListAsync(ct), ct);
        await Task.WhenAll(count, revenue, top);
        return new Dashboard(await count, await revenue, await top);
    }

    private async Task<T> RunAsync<T>(
        Func<ShopDb, Task<T>> query, CancellationToken ct)
    {
        // Each query gets its own context, and its own connection
        await using var db = await factory.CreateDbContextAsync(ct);
        return await query(db);
    }
}
